'use strict';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const notice=(text,error=false)=>{const el=$('#notice');el.textContent=text;el.classList.toggle('error',error)};
let courses=[],lessons=[];
const token=()=>$('#admin-token').value.trim();
async function api(path,options={}){const response=await fetch(path,{...options,headers:{...(options.body?{'content-type':'application/json'}:{}),'x-academy-admin-token':token(),...(options.headers||{})}});const data=await response.json().catch(()=>({}));if(!response.ok)throw Error(data.error||`Request failed (${response.status})`);return data}
const namesFrom=form=>form.elements.names.value.split(',').map(name=>name.trim()).filter(Boolean);
function updateSelectors(){const select=$('#lesson-form [name=courseId]'),current=select.value;select.innerHTML=courses.map(course=>`<option value="${esc(course.id)}">${esc(course.title)}</option>`).join('');if(courses.some(course=>course.id===current))select.value=current}
function paintLessons(){const host=$('#lesson-list');host.innerHTML=lessons.length?lessons.map(lesson=>`<article class="lesson-review" data-id="${esc(lesson.id)}"><div class="lesson-meta"><span>${esc(lesson.courseTitle||'Course')}</span><span class="tag ${lesson.status==='approved'?'good':''}">${esc(lesson.status)}</span><span class="tag ${lesson.qa?.ok?'good':'bad'}">${lesson.qa?.ok?'Numbers and names passed':'QA failed'}</span></div><h3>${esc(lesson.title)}</h3><label>English source<textarea data-field="sourceText" rows="4" ${lesson.status==='approved'?'disabled':''}>${esc(lesson.sourceText)}</textarea></label><label>Telugu preview<textarea data-field="teluguText" rows="4" ${lesson.status==='approved'?'disabled':''}>${esc(lesson.teluguText)}</textarea></label><p class="small">${lesson.qa?.ok?'All numeric tokens and listed names are present. Human language review is still required.':`Missing numbers: ${(lesson.qa?.missingNumbers||[]).join(', ')||'none'}; extra numbers: ${(lesson.qa?.extraNumbers||[]).join(', ')||'none'}; missing terms: ${(lesson.qa?.missingNames||[]).join(', ')||'none'}`}</p><div class="actions">${lesson.status==='draft'?`<button class="button secondary" data-save="${esc(lesson.id)}">Save edited preview</button><button class="button" data-approve="${esc(lesson.id)}" ${lesson.qa?.ok?'':'disabled'}>Approve and publish</button>`:''}</div></article>`).join(''):'<p class="small">No saved lessons yet.</p>'}
async function refresh(){try{const [courseData,lessonData]=await Promise.all([api('/api/academy/admin/courses'),api('/api/academy/admin/lessons')]);courses=courseData.courses;lessons=lessonData.lessons;updateSelectors();paintLessons();$('#admin').hidden=false;notice('Connected. New lessons remain private drafts until reviewed and approved.')}catch(error){$('#admin').hidden=true;notice(error.message,true)}}
$('#connect').addEventListener('click',async()=>{if(!token())return notice('Enter the admin token configured on the server.',true);await refresh()});
$('#course-form').addEventListener('submit',async event=>{event.preventDefault();try{const form=new FormData(event.currentTarget);await api('/api/academy/admin/courses',{method:'POST',body:JSON.stringify({title:form.get('title'),description:form.get('description')||''})});event.currentTarget.reset();await refresh()}catch(error){notice(error.message,true)}});
$('#lesson-file').addEventListener('change',async event=>{const file=event.target.files?.[0];if(file){$('#lesson-form [name=sourceText]').value=await file.text();notice(`Loaded ${file.name}. Check the lesson text before submitting.`)}});
$('#translate').addEventListener('click',async()=>{const form=$('#lesson-form'),sourceText=form.elements.sourceText.value;if(!sourceText.trim())return notice('Add English lesson text first.',true);const button=$('#translate');button.disabled=true;try{const result=await api('/api/academy/admin/translate',{method:'POST',body:JSON.stringify({sourceText,names:namesFrom(form)})});form.elements.teluguText.value=result.teluguText;notice(result.qa.ok?'Translation ready; automated number and name QA passed. Review the Telugu before saving.':'Translation ready with QA issues. Review and correct the Telugu text before saving.',!result.qa.ok)}catch(error){notice(error.message,true)}finally{button.disabled=false}});
$('#lesson-form').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,body={courseId:form.elements.courseId.value,title:form.elements.title.value,sourceText:form.elements.sourceText.value,teluguText:form.elements.teluguText.value,names:namesFrom(form)};try{const result=await api('/api/academy/admin/lessons',{method:'POST',body:JSON.stringify(body)});form.reset();updateSelectors();await refresh();notice(result.lesson.qa.ok?'Draft saved. Check both languages and approve when ready.':'Draft saved with QA issues; fix the missing numbers or names before approval.',!result.lesson.qa.ok)}catch(error){notice(error.message,true)}});
document.addEventListener('click',async event=>{const save=event.target.closest('[data-save]'),approve=event.target.closest('[data-approve]');if(!save&&!approve)return;const button=save||approve,card=button.closest('[data-id]');button.disabled=true;try{if(save){const body={title:card.querySelector('h3').textContent,sourceText:card.querySelector('[data-field="sourceText"]').value,teluguText:card.querySelector('[data-field="teluguText"]').value,names:lessons.find(x=>x.id===save.dataset.save)?.names||[]};const result=await api('/api/academy/admin/lessons/'+encodeURIComponent(save.dataset.save),{method:'PUT',body:JSON.stringify(body)});notice(result.lesson.qa.ok?'Edited draft saved; review the translation before approval.':'Draft saved with QA issues.',!result.lesson.qa.ok)}else{await api('/api/academy/admin/lessons/'+encodeURIComponent(approve.dataset.approve)+'/approve',{method:'POST',body:'{}'});notice('Lesson approved and visible to learners.')}await refresh()}catch(error){notice(error.message,true);button.disabled=false}});
if(token())refresh();
